-- Hin Lim's furniture from Houzs Century's CRM product list ("Houz Century CRM Product List.xlsx", sheet RptSKUEnquiry,
-- SKU Type = SALES: 581 of 1,155 rows), owner 19 Nov 2026. Review: docs/catalog-import/crm-hinlim/review.xlsx.
--  * Our code = <TYPE>-HLM-<Hin Lim code> (SOF / BED / MAT / FUR / ACC by sub-category); the list's
--    "SKU Code" is Hin Lim's own code and goes on the supplier link (supplier_sku).
--  * Group FURNITURE, sub-category from the description's keywords (rules: build.py RULES, review.xlsx "Rules"):
--    Dining 196, Loose storage 134, Tables 129, Sofa 87, Bedframe 21, Accessory 14.
--  * Name = SKU Description; branding = the list's brand (NESTHOUZ 213, NUHOOM 200, LUOOMA 68, NESTNORDIC 50, NUHOOM - BASIC 27, FYND 23);
--    description = size, colour, material, assembly, pack, carton, weights, cubic, Hin Lim code; unit_m3_milli = Cubic x 1000;
--    unit SET for a "1SET/..." pack or a "SET OF" name, else PCS; cost_price_sen = Houzs Century Cost Price (MYR) x 100; no selling price.
--  * Each SKU a model of its own (model_code = SKU code), Active, company 1 (The Conts).
--  * Main supplier HIN LIM FURNITURE MANUFACTURER SDN BHD (400-H004): one scm.supplier_material_bindings row per SKU (material_kind
--    mfg_product, supplier_sku = Hin Lim code, unit_price_sen = cost, valid from 2026-11-19, main unless the SKU already has a
--    main supplier, not a cost anchor) and one scm.supplier_binding_price_history row per priced link (581).
--    The supplier is created only where it is missing (a fresh local / CI database); production has it.
--  * 9 old generic SKUs that are the same item (FUR-GEN-COF-HIACE, FUR-GEN-COF-SANDRA2, FUR-GEN-SIDE-HIRADO, FUR-GEN-DIN-AIMON, SOF-GEN-NEXON-3S, FUR-GEN-CHAIR-CARTER, FUR-GEN-CHAIR-ZOLA, FUR-GEN-CHAIR-MACY, FUR-MUJ-TVCAB)
--    become INACTIVE (the SKU Master's Deactivate), only where still ACTIVE, each written to scm.entity_audit_log. They are
--    not deleted or renamed: existing documents name them and keep showing their code. The SO / VO pickers offer ACTIVE
--    SKUs only, so they now find the Hin Lim codes. Replacements: review.xlsx "Retired old codes".
-- Built by docs/catalog-import/crm-hinlim/build.py; edit that script, not this file. Safe to run again: everything is keyed on
-- SKU code / supplier + SKU, an existing code is left as it is.
-- APPLY: production through the GitHub workflow "Apply migrations to production" with only=0346, dry run first.

set local search_path = scm, public, extensions;

insert into scm.suppliers (id, company_id, code, name, status, notes)
select 'f98aa7d5-2bf3-4543-b0ff-cbbc4c5f9360'::uuid, 1, '400-H004', 'HIN LIM FURNITURE MANUFACTURER SDN BHD', 'ACTIVE', 'Created by crm-hinlim 2026-11-19 (missing on this database)'
 where exists (select 1 from public.companies where id = 1)
   and not exists (select 1 from scm.suppliers s where s.id = 'f98aa7d5-2bf3-4543-b0ff-cbbc4c5f9360'::uuid
                      or (s.company_id = 1 and upper(s.code) = '400-H004'));

create temp table hlm_rows on commit drop as
select x.*, (select s.id from scm.suppliers s where s.company_id = 1
               and (s.id = 'f98aa7d5-2bf3-4543-b0ff-cbbc4c5f9360'::uuid or upper(s.code) = '400-H004')
             order by (s.id = 'f98aa7d5-2bf3-4543-b0ff-cbbc4c5f9360'::uuid) desc limit 1) as supplier_id
  from jsonb_to_recordset($hlm$[
