  as x(id text, code text, name text, sub_category text, uom text, cost integer, m3 integer, branding text, description text,
       supplier_sku text)
 where exists (select 1 from public.companies where id = 1);

insert into scm.product_models (company_id, model_code, name, category)
select 1, r.code, r.name, 'FURNITURE'::scm.mfg_product_category from hlm_rows r
on conflict (company_id, model_code, category) do nothing;

insert into scm.mfg_products
    (id, company_id, code, name, category, category_group, sub_category, uom, status, cost_price_sen, unit_m3_milli,
     branding, description, model_id)
select r.id, 1, r.code, r.name, 'FURNITURE'::scm.mfg_product_category, 'FURNITURE', r.sub_category, r.uom, 'ACTIVE',
       r.cost, r.m3, r.branding, r.description, m.id
  from hlm_rows r
  left join scm.product_models m on m.company_id = 1 and m.model_code = r.code and m.category = 'FURNITURE'
on conflict (company_id, code) do nothing;

insert into scm.supplier_material_bindings
    (company_id, supplier_id, material_kind, item_code, material_name, supplier_sku, unit_price_sen, price_valid_from,
     is_main_supplier, notes)
select 1, r.supplier_id, 'mfg_product', r.code, r.name, r.supplier_sku, r.cost, case when r.cost > 0 then date '2026-11-19' end,
       not exists (select 1 from scm.supplier_material_bindings b where b.company_id = 1 and b.material_kind = 'mfg_product'
                                                                  and b.item_code = r.code and b.is_main_supplier),
       'crm-hinlim 2026-11-19: main supplier, cost from the Houzs Century CRM product list'
  from hlm_rows r
 where not exists (select 1 from scm.supplier_material_bindings b where b.company_id = 1 and b.material_kind = 'mfg_product'
                                                                  and b.item_code = r.code and b.supplier_id = r.supplier_id);

insert into scm.supplier_binding_price_history
    (company_id, supplier_id, material_kind, item_code, unit_price_sen, is_main_supplier, effective_from, notes, created_by, applied_at)
select 1, r.supplier_id, 'mfg_product', r.code, r.cost, true, date '2026-11-19', 'crm-hinlim 2026-11-19: Houzs Century Cost Price', 'crm-hinlim 2026-11-19', now()
  from hlm_rows r
 where r.cost > 0
   and not exists (select 1 from scm.supplier_binding_price_history h where h.company_id = 1 and h.supplier_id = r.supplier_id
                     and h.material_kind = 'mfg_product' and h.item_code = r.code and h.effective_from = date '2026-11-19');

insert into scm.app_config (key, value, description, company_id)
select 'note:crm-hinlim-2026-11-19', '{"tag": "crm-hinlim 2026-11-19", "skus": 581, "supplier": "400-H004"}',
       'Import note: crm-hinlim 2026-11-19, Hin Lim SKUs from the Houzs Century CRM product list', 1
 where exists (select 1 from public.companies where id = 1)
on conflict (key) do nothing;

do $$ begin
  if exists (select 1 from public.companies where id = 1) and
     (select count(*) from hlm_rows r join scm.supplier_material_bindings b on b.company_id = 1 and b.material_kind = 'mfg_product'
        and b.item_code = r.code and b.supplier_id = r.supplier_id
        join scm.mfg_products p on p.company_id = 1 and p.code = r.code) <> 581
  then raise exception 'expected 581 Hin Lim SKUs, each with its Hin Lim link'; end if;
end $$;

-- Old generic SKUs replaced by the Hin Lim codes: audit first, then the same status change the SKU Master's Deactivate makes.
create temp table hlm_retire on commit drop as
select x.code, x.replaced_by
  from jsonb_to_recordset($hlm$[{"code": "FUR-GEN-COF-HIACE", "replaced_by": "FUR-HLM-133060, FUR-HLM-133061"}, {"code": "FUR-GEN-COF-SANDRA2", "replaced_by": "FUR-HLM-132053, FUR-HLM-132055"}, {"code": "FUR-GEN-SIDE-HIRADO", "replaced_by": "FUR-HLM-131196, FUR-HLM-151043, FUR-HLM-151044"}, {"code": "FUR-GEN-DIN-AIMON", "replaced_by": "FUR-HLM-144020, FUR-HLM-145071"}, {"code": "SOF-GEN-NEXON-3S", "replaced_by": "SOF-HLM-233315, SOF-HLM-233321"}, {"code": "FUR-GEN-CHAIR-CARTER", "replaced_by": "FUR-HLM-241317, FUR-HLM-241318"}, {"code": "FUR-GEN-CHAIR-ZOLA", "replaced_by": "FUR-HLM-241428, FUR-HLM-241534, FUR-HLM-241561"}, {"code": "FUR-GEN-CHAIR-MACY", "replaced_by": "FUR-HLM-241506, FUR-HLM-241507, FUR-HLM-241663"}, {"code": "FUR-MUJ-TVCAB", "replaced_by": "FUR-HLM-336103"}]$hlm$::jsonb)
  as x(code text, replaced_by text);

insert into scm.entity_audit_log (company_id, entity_type, entity_id, action, actor_name_snapshot, field_changes, source, note)
select 1, 'mfg_product', p.code, 'deactivate', 'migration 0346', '[]'::jsonb, 'migration',
       'crm-hinlim 2026-11-19: retired, owner 19 Nov 2026: the same item is now on Hin Lim codes ' || r.replaced_by || '; status ACTIVE -> INACTIVE, kept for the documents that name it'
  from scm.mfg_products p join hlm_retire r on r.code = p.code
 where p.company_id = 1 and p.status = 'ACTIVE';

update scm.mfg_products p set status = 'INACTIVE', updated_at = now()
  from hlm_retire r
 where p.company_id = 1 and p.code = r.code and p.status = 'ACTIVE';
